      ]
    },
    {
      "id": "C1-05",
      "ja": "この秘密を",
      "budget": {
        "min": 6,
        "max": 6
      },
      "pattern": [
        6
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "一遍一遍"
        },
        {
          "id": "C1-02",
          "zh": "一遍一遍 呼喊"
        },
        {
          "id": "C1-03",
          "zh": "就算变成夜色 深处的怪兽 也不回头"
        },
        {
          "id": "C1-04",
          "zh": "想在这 留下一句 没说出的心事"
        },
        {
          "id": "C1-05",
          "zh": "把这一句秘密"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "一遍一遍"
        },
        {
          "id": "C1-02",
          "zh": "一遍一遍地喊"
        },
        {
          "id": "C1-03",
          "zh": "变成这黑夜里 沉默的怪兽 也不逃走"
        },
        {
          "id": "C1-04",
          "zh": "想留下 一点什么 在夜的角落里"
        },
        {
          "id": "C1-05",
          "zh": "把这秘密留住"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "无论多少次"
        },
        {
          "id": "C1-02",
          "zh": "无论多少次呼喊"
        },
        {
          "id": "C1-03",
          "zh": "即使成为这暗夜中的怪兽"
        },
        {
          "id": "C1-04",
          "zh": "我仍想留在这里啊"
        },
        {
          "id": "C1-05",
          "zh": "这个秘密"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "无论几次"
        },
        {
          "id": "C1-02",
          "zh": "无论几次呼喊"
        },
        {
          "id": "C1-03",
          "zh": "即使我变成这黑暗夜晚之中的怪兽"
        },
        {
          "id": "C1-04",
          "zh": "我真的渴望能把它留在这地方"
        },
        {
          "id": "C1-05",
          "zh": "这一个秘密啊"
        }
      ]
    }
  ]
}

